-- Current pre-launch policies. Apply after legacy content seeds.
BEGIN;
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('privacy','سياسة الخصوصية وحماية البيانات (متوافقة مع GDPR)','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"privacy-0","type":"text","props":{"title":"سياسة الخصوصية وحماية البيانات (متوافقة مع GDPR)","body":"ترحب بكم For Relief Humanitarian Foundation، ونلتزم بحماية خصوصيتكم والحفاظ على سرية بياناتكم الشخصية. توضح هذه السياسة كيفية جمع بياناتكم واستخدامها وتخزينها وحمايتها عند استخدام موقعنا الإلكتروني أو خدماتنا الرقمية أو التبرع عبر منصتنا."}},{"id":"privacy-1","type":"text","props":{"title":"البيانات التي نجمعها","body":"• الاسم الكامل\n• عنوان البريد الإلكتروني\n• رقم الهاتف\n• عنوان الإقامة أو الدولة\n• بيانات التبرعات والمعاملات المالية\n• معلومات الحساب عند التسجيل\n• بيانات التواصل والاستفسارات\n• المعلومات التقنية: عنوان IP ونوع المتصفح وملفات تعريف الارتباط"}},{"id":"privacy-2","type":"text","props":{"title":"كيفية استخدام البيانات","body":"• معالجة التبرعات والمدفوعات\n• إنشاء وإدارة حسابات المستخدمين\n• التواصل مع المتبرعين والمستفيدين والشركاء\n• إرسال الإيصالات والتقارير والتحديثات\n• تحسين خدمات الموقع وتجربة المستخدم\n• الامتثال للمتطلبات القانونية والتنظيمية\n• منع الاحتيال وتعزيز أمن المنصة"}},{"id":"privacy-3","type":"text","props":{"title":"حماية البيانات","body":"نطبق تدابير تقنية وإدارية متقدمة تشمل تشفير البيانات أثناء النقل والتخزين، واستخدام خوادم آمنة، وضوابط صارمة للتحكم في الوصول، ومراقبة أمنية مستمرة. لا نقوم ببيع أو تأجير أو المتاجرة ببياناتكم الشخصية."}},{"id":"privacy-4","type":"text","props":{"title":"حقوقكم وفقاً للائحة GDPR","body":"• الوصول إلى بياناتكم الشخصية\n• تصحيح البيانات غير الدقيقة\n• طلب حذف البيانات عندما يسمح القانون بذلك\n• تقييد معالجة البيانات\n• الاعتراض على بعض أنواع المعالجة\n• سحب الموافقة في أي وقت\n• طلب نقل البيانات إلى مزود آخر\n• تقديم شكوى إلى الجهة الرقابية المختصة"}},{"id":"privacy-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('terms','الإطار القانوني','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"terms-0","type":"text","props":{"title":"الإطار القانوني","body":"• تلتزم المنصة بتشريعات حماية المستهلك والتجارة الإلكترونية\n• متطلبات مكافحة غسل الأموال وتمويل الإرهاب\n• حماية البيانات الشخصية وفق المعايير الدولية\n• أفضل ممارسات الحوكمة للمؤسسات غير الربحية"}},{"id":"terms-1","type":"text","props":{"title":"أهلية الاستخدام","body":"• تكون مؤهلاً قانونياً لإبرام العقود وفق قوانين بلدك\n• تقدم معلومات صحيحة ودقيقة ومحدثة\n• تستخدم وسائل دفع قانونية ومصرحاً لك باستخدامها\n• تمتثل لجميع القوانين واللوائح المعمول بها"}},{"id":"terms-2","type":"text","props":{"title":"التبرعات","body":"• التبرع يتم بإرادتك الحرة والأموال مصدرها مشروع\n• قد تعيد المؤسسة توجيه التبرعات إلى مشروع مماثل إذا اكتمل تمويل المشروع المختار\n• لا يُعد التبرع عملية شراء أو استثماراً يضمن نتائج محددة"}},{"id":"terms-3","type":"text","props":{"title":"التزامات المؤسسة","body":"• إدارة التبرعات بمسؤولية ونزاهة\n• إصدار إيصالات إلكترونية فورية\n• نشر تقارير مالية وتقارير أثر دورية\n• حماية البيانات الشخصية وفق سياسة الخصوصية\n• تطبيق أعلى معايير الشفافية والمساءلة والحوكمة"}},{"id":"terms-4","type":"text","props":{"title":"دقة المعلومات والاستخدام المقبول","body":"إذا لاحظت خطأ أو معلومة تحتاج إلى تحديث، أرسل رابط الصفحة إلى البريد الرسمي. إجابات المساعد الآلي قد تخطئ ولا تُعد تأكيداً رسمياً من المؤسسة. لا تستخدم الموقع للإساءة أو انتحال الهوية أو إرسال معلومات مالية حساسة."}},{"id":"terms-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('refund-policy','حالة الاسترداد حالياً','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"refund-policy-0","type":"text","props":{"title":"حالة الاسترداد حالياً","body":"لم تُفتح قنوات استقبال التبرعات بعد؛ لذلك لا نعرض حالياً إجراءً تنفيذياً أو مدة مضمونة لاسترداد تبرعات عبر الموقع. سنوضح شروط الدفع والاسترداد قبل فتح القنوات."}},{"id":"refund-policy-1","type":"text","props":{"title":"إذا أرسلت مبلغاً أو تلقيت طلب دفع","body":"راسل info@forrelief.org مع تاريخ الواقعة والجهة أو الرابط المستخدم ووصف مختصر. لا ترسل بيانات البطاقة أو رموز التحقق. نراجع ما يمكن التحقق منه؛ لا يمكننا ضمان استرداد مبلغ أُرسل إلى جهة أخرى أو تأكيد صلة أي طلب دفع بالمؤسسة قبل فحصه."}},{"id":"refund-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('cookie-policy','كيف نستخدمها؟','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"cookie-policy-0","type":"text","props":{"title":"كيف نستخدمها؟","body":"• تشغيل الوظائف الأساسية للموقع وضمان عمله بشكل صحيح\n• حفظ تفضيلات المستخدم وإعداداته لتحسين تجربة التصفح\n• تحليل أداء الموقع وقياس عدد الزيارات وسلوك المستخدمين\n• تعزيز أمن الموقع والكشف عن الأنشطة غير المشروعة\n• تحسين المحتوى والخدمات بما يتناسب مع احتياجات الزوار"}},{"id":"cookie-policy-1","type":"text","props":{"title":"إدارة ملفات تعريف الارتباط","body":"يمكنك قبول أو رفض أو حذف ملفات تعريف الارتباط في أي وقت من خلال إعدادات متصفحك. تعطيل بعضها قد يؤثر في أداء بعض وظائف الموقع."}},{"id":"cookie-policy-2","type":"text","props":{"title":"التخزين في المتصفح","body":"يستخدم الموقع ملفات جلسة لتسجيل الدخول، وتخزيناً محلياً لبعض التفضيلات مثل اختيار ملفات الارتباط وسلة الموقع. يمكن حذف هذه البيانات من إعدادات المتصفح، وقد يؤدي ذلك إلى تسجيل الخروج أو فقدان التفضيلات."}},{"id":"cookie-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('aml-policy','خبرة مؤسسية والتزام مسؤول','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"aml-policy-0","type":"text","props":{"title":"خبرة مؤسسية والتزام مسؤول","body":"مؤسستنا مستقلة حالياً، ونستند في عملنا إلى خبرة مؤسسية ممتدة. ونلتزم بحماية الثقة التي يضعها فينا الداعمون والشركاء، وتطبيق إجراءات تتناسب مع طبيعة أنشطتنا والمتطلبات القانونية ذات الصلة. قنوات التبرع عبر الموقع لم تُفتح بعد؛ وتعبّر الالتزامات أدناه عن نهجنا المؤسسي في التعامل مع الأموال والشراكات."}},{"id":"aml-policy-1","type":"text","props":{"title":"التزاماتنا","body":"• تطبيق إجراءات فعالة لمكافحة غسل الأموال وتمويل الإرهاب والاحتيال.\n• حماية أموال المتبرعين وضمان استخدامها في الأغراض الإنسانية المخصصة لها.\n• التحقق من هوية الشركاء والجهات المتعاملة عند الاقتضاء.\n• مراقبة المعاملات المالية للكشف عن أي نشاط غير اعتيادي أو مشبوه.\n• التعاون مع الجهات الرقابية والتنظيمية المختصة وفقاً للمتطلبات القانونية."}},{"id":"aml-policy-2","type":"text","props":{"title":"الإطار المرجعي","body":"• توصيات مجموعة العمل المالي (FATF).\n• متطلبات مكافحة غسل الأموال وتمويل الإرهاب (AML/CFT).\n• أنظمة العقوبات الدولية حيثما تنطبق.\n• التشريعات الوطنية ذات الصلة في الدول التي تعمل فيها المؤسسة."}},{"id":"aml-policy-3","type":"text","props":{"title":"مسؤوليات المستخدم","body":"• أن تكون الأموال المستخدمة في التبرعات من مصدر مشروع.\n• تقديم معلومات صحيحة وكاملة.\n• عدم استخدام المنصة لأي نشاط غير قانوني أو احتيالي.\n• الالتزام بالقوانين والأنظمة السارية في دولة الإقامة."}},{"id":"aml-policy-4","type":"text","props":{"title":"الإبلاغ عن طلب مشبوه","body":"إذا وصلتك رسالة تطلب تحويلاً باسم المؤسسة، أرسل رابطها أو وصفها إلى البريد الرسمي للتحقق. لا تشارك كلمات المرور أو رموز التحقق، ولا تعتبر وجود الشعار دليلاً كافياً على صحة الطلب."}},{"id":"aml-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('complaints','بريد واحد لجميع الطلبات','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"complaints-0","type":"text","props":{"title":"بريد واحد لجميع الطلبات","body":"الاستفسارات والشكاوى وطلبات الخصوصية والتواصل الإعلامي والشراكات تُستقبل حالياً عبر info@forrelief.org. لا توجد عناوين بريد منفصلة معلنة لهذه الأقسام. اكتب نوع الطلب في عنوان الرسالة ليسهل توجيهه."}},{"id":"complaints-1","type":"text","props":{"title":"كيف تقدم ملاحظة أو شكوى؟","body":"اذكر رابط الصفحة أو تاريخ الواقعة ووصف المشكلة وطريقة التواصل المناسبة. أرسل فقط المعلومات الضرورية. سنطلب توضيحات إذا احتاجت المراجعة إليها؛ نرد خلال 24 ساعة، ونوضح الخطوة التالية وما إذا كانت المعالجة تحتاج إلى وقت إضافي. إذا كان طلبك يتعلق بتحويل مالي، أرفق تاريخه والجهة المستلمة دون بيانات مصرفية حساسة."}},{"id":"complaints-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('financial-transparency','المعلومات المتاحة','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"financial-transparency-0","type":"text","props":{"title":"المعلومات المتاحة","body":"لم تُفتح قنوات التبرع عبر الموقع بعد. لا ينبغي اعتبار العدادات أو أهداف الحملات أو الصور المنشورة قوائم مالية أو دليلاً على مبالغ جُمعت من خلال المنصة."}},{"id":"financial-transparency-1","type":"text","props":{"title":"التقارير والاستفسارات","body":"نبني معلوماتنا المالية على مستندات يمكن الرجوع إليها. عند نشر تقرير، ينبغي أن يوضح الفترة التي يغطيها ومصدره، وما إذا خضع لتدقيق مستقل. يمكنك طلب معلومات عن مشروع أو تقرير محدد عبر البريد الرسمي. ننشر نسب المصروفات وتخصيص الأموال عندما تتوفر بيانات تدعمها."}},{"id":"financial-transparency-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('how-we-use-donations','قبل فتح قنوات التبرع','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"how-we-use-donations-0","type":"text","props":{"title":"قبل فتح قنوات التبرع","body":"لم يبدأ استقبال التبرعات عبر قنوات الموقع. وصف المشاريع يوضح مجال العمل أو الاحتياج، ولا يُعد وعداً بتخصيص نسبة ثابتة من تبرع لم يُستقبل بعد."}},{"id":"how-we-use-donations-1","type":"text","props":{"title":"المعلومات المطلوبة عند الإطلاق","body":"عند فتح قنوات التبرع، ستوضح المعلومات المنشورة الغرض من الحملة وأي تكاليف أو قيود أو شروط ذات صلة. لا نَعِد حالياً بأن كامل كل تبرع يصل إلى المستفيدين، أو بموعد تنفيذ محدد، دون بيانات موثقة."}},{"id":"how-we-use-donations-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
INSERT INTO "Page" ("slug","title","description","sections","isPublished","showInMenu","isSystem","order","createdAt","updatedAt") VALUES ('license','المحتوى والعلامات','قنوات التبرع لم تُفتح بعد. سنعلن بدء استقبال التبرعات عند جاهزيتها.','[{"id":"license-0","type":"text","props":{"title":"المحتوى والعلامات","body":"قد تتضمن صفحات الموقع نصوصاً وصوراً وعلامات تخص المؤسسة أو أصحاب حقوق آخرين. للاستفسار عن إعادة استخدام محتوى محدد أو الإبلاغ عن مشكلة في نسبته، أرسل رابطه إلى البريد الرسمي."}},{"id":"license-1","type":"text","props":{"title":"الوثائق والمعلومات الرسمية","body":"وجود الموقع أو اسم المؤسسة أو رابط سجل عام لا يثبت بمفرده ترخيصاً لجمع التبرعات أو إعفاءً ضريبياً أو اعتماداً أمنياً. قنوات التبرع لم تُفتح بعد، ويمكن طلب معلومات محددة عن الوثائق المتاحة عبر البريد الرسمي."}},{"id":"license-contact","type":"text","props":{"title":"info@forrelief.org","body":"البريد الرسمي الوحيد لجميع الاستفسارات هو info@forrelief.org. يرجى توضيح موضوع الرسالة، مثل شكوى أو خصوصية أو شراكة. نرد على الرسائل الواردة إلى info@forrelief.org خلال 24 ساعة. قد تتطلب معالجة الطلب أو حله وقتاً إضافياً بحسب طبيعته."}}]'::jsonb,true,false,true,10,now(),now()) ON CONFLICT ("slug") DO UPDATE SET "description"=EXCLUDED."description","sections"=EXCLUDED."sections","updatedAt"=now();
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"privacy-0","type":"text","props":{"title":"Privacy and data protection policy (GDPR compliant)","body":"For Relief Humanitarian Foundation welcomes you. We are committed to protecting your privacy and maintaining the confidentiality of your personal data. This policy explains how we collect, use, store and protect your data when you use our website or digital services or donate through our platform."}},{"id":"privacy-1","type":"text","props":{"title":"Data we collect","body":"• Full name\n• Email address\n• Phone number\n• Residential address or country\n• Donation and financial transaction data\n• Account information on registration\n• Communications and enquiries\n• Technical information: IP address, browser type and cookies"}},{"id":"privacy-2","type":"text","props":{"title":"How we use data","body":"• Process donations and payments\n• Create and manage user accounts\n• Communicate with donors, beneficiaries and partners\n• Send receipts, reports and updates\n• Improve website services and user experience\n• Comply with legal and regulatory requirements\n• Prevent fraud and strengthen platform security"}},{"id":"privacy-3","type":"text","props":{"title":"Data protection","body":"We apply advanced technical and administrative measures, including encryption in transit and at rest, secure servers, strict access controls and continuous security monitoring. We do not sell, rent or trade your personal data."}},{"id":"privacy-4","type":"text","props":{"title":"Your rights under the GDPR","body":"• Access your personal data\n• Correct inaccurate data\n• Request deletion where permitted by law\n• Restrict data processing\n• Object to certain types of processing\n• Withdraw consent at any time\n• Request transfer of data to another provider\n• Lodge a complaint with the competent supervisory authority"}},{"id":"privacy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='privacy');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"terms-0","type":"text","props":{"title":"Legal framework","body":"• The platform complies with consumer protection and e-commerce legislation\n• Anti-money laundering and counter-terrorist financing requirements\n• Personal data protection in accordance with international standards\n• Best governance practices for nonprofit organisations"}},{"id":"terms-1","type":"text","props":{"title":"Eligibility to use the platform","body":"• You must have legal capacity to enter into contracts under the laws of your country\n• Provide truthful, accurate and up-to-date information\n• Use lawful payment methods that you are authorised to use\n• Comply with all applicable laws and regulations"}},{"id":"terms-2","type":"text","props":{"title":"Donations","body":"• Donations are voluntary and funds must come from lawful sources\n• The organisation may redirect donations to a similar project if the selected project is fully funded\n• A donation is not a purchase or an investment guaranteeing specific results"}},{"id":"terms-3","type":"text","props":{"title":"The organisation’s commitments","body":"• Manage donations responsibly and with integrity\n• Issue immediate electronic receipts\n• Publish periodic financial and impact reports\n• Protect personal data in accordance with the privacy policy\n• Apply the highest standards of transparency, accountability and governance"}},{"id":"terms-4","type":"text","props":{"title":"Accuracy and acceptable use","body":"If you notice an error or information that needs updating, send the page link to the official email. Automated assistant answers may be incorrect and are not official confirmation from the organisation. Do not use the website for abuse, impersonation or sending sensitive financial information."}},{"id":"terms-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='terms');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"refund-policy-0","type":"text","props":{"title":"Current refund status","body":"Donation channels are not open, so we do not currently offer an operational refund process or guaranteed refund times for website donations. Payment and refund terms will be explained before channels open."}},{"id":"refund-policy-1","type":"text","props":{"title":"If you sent money or received a payment request","body":"Email info@forrelief.org with the date, recipient or link used and a brief description. Do not send card details or verification codes. We can review available information but cannot guarantee recovery of money sent to another party or confirm a request''s connection to the organisation without checking it."}},{"id":"refund-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='refund-policy');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"cookie-policy-0","type":"text","props":{"title":"How do we use them?","body":"• Operate essential website features and ensure the site works correctly\n• Save user preferences and settings to improve browsing\n• Analyse website performance, visitor numbers and user behaviour\n• Strengthen website security and detect unlawful activity\n• Improve content and services to meet visitors’ needs"}},{"id":"cookie-policy-1","type":"text","props":{"title":"Managing cookies","body":"You can accept, reject or delete cookies at any time through your browser settings. Disabling some cookies may affect how certain website features work."}},{"id":"cookie-policy-2","type":"text","props":{"title":"Browser storage","body":"The website uses session cookies for login and local storage for preferences such as cookie choices and the website basket. You can delete this data through your browser settings, which may sign you out or remove your preferences."}},{"id":"cookie-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='cookie-policy');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"aml-policy-0","type":"text","props":{"title":"Institutional experience and responsible practice","body":"Our organisation is currently independent and draws on longstanding institutional experience. We are committed to the trust of our supporters and partners through procedures appropriate to our activities and applicable legal requirements. Website donation channels are not yet open; the commitments below describe our institutional approach to funds and partnerships."}},{"id":"aml-policy-1","type":"text","props":{"title":"Our commitments","body":"• Apply effective measures against money laundering, terrorist financing and fraud.\n• Protect donor funds and ensure they are used for their designated humanitarian purposes.\n• Verify the identity of partners and counterparties where appropriate.\n• Monitor financial transactions for unusual or suspicious activity.\n• Cooperate with competent regulatory and supervisory authorities as legally required."}},{"id":"aml-policy-2","type":"text","props":{"title":"Reference framework","body":"• Financial Action Task Force (FATF) recommendations.\n• Anti-money laundering and counter-terrorist financing (AML/CFT) requirements.\n• International sanctions regimes where applicable.\n• Relevant national legislation in the countries where the organisation operates."}},{"id":"aml-policy-3","type":"text","props":{"title":"User responsibilities","body":"• Donation funds must come from lawful sources.\n• Provide accurate and complete information.\n• Do not use the platform for unlawful or fraudulent activity.\n• Comply with applicable laws and regulations in your country of residence."}},{"id":"aml-policy-4","type":"text","props":{"title":"Report a suspicious request","body":"If you receive a transfer request in the organisation''s name, send its link or a description to the official email for verification. Do not share passwords or verification codes; a logo alone does not establish that a request is genuine."}},{"id":"aml-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='aml-policy');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"complaints-0","type":"text","props":{"title":"One inbox for all enquiries","body":"General enquiries, complaints, privacy requests, media and partnership enquiries currently use info@forrelief.org. We do not advertise separate departmental inboxes. State your topic in the subject line so the message can be directed appropriately."}},{"id":"complaints-1","type":"text","props":{"title":"How to raise an issue","body":"Include the page link or incident date, a description and a suitable contact method. Share only necessary information. Further details may be requested, and we reply within 24 hours, explaining the next step and whether more time is needed. For a payment-related enquiry, note that donation channels have not opened."}},{"id":"complaints-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='complaints');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"financial-transparency-0","type":"text","props":{"title":"Available information","body":"Website donation channels have not opened. Counters, campaign targets and published images should not be treated as financial statements or evidence of money raised through this platform."}},{"id":"financial-transparency-1","type":"text","props":{"title":"Reports and enquiries","body":"This page does not claim independent financial audits or published reports unless the document, period and source are provided. To ask about a particular report or project, name it in an email. We do not state expense or allocation percentages without supporting records."}},{"id":"financial-transparency-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='financial-transparency');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"how-we-use-donations-0","type":"text","props":{"title":"Before donation channels open","body":"Donations are not yet being accepted through website channels. Project descriptions explain activities or needs; they are not a promise to allocate a fixed share of a donation that has not been received."}},{"id":"how-we-use-donations-1","type":"text","props":{"title":"Information at launch","body":"When channels open, published information will explain campaign purposes and relevant costs, restrictions and conditions. We do not currently promise that every donation reaches beneficiaries in full or guarantee delivery dates without documented information."}},{"id":"how-we-use-donations-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='how-we-use-donations');
UPDATE "PageTranslation" SET "description"='Donation channels are not open yet. We will announce when donations can be accepted.',"sections"='[{"id":"license-0","type":"text","props":{"title":"Content and brands","body":"Website text, images and brands may belong to the organisation or other rights holders. Email the specific page link to ask about reuse or report an attribution issue."}},{"id":"license-1","type":"text","props":{"title":"Limits of this page","body":"The website, organisation name or a public-register link does not by itself establish fundraising authorisation, tax exemption or security accreditation. Donation channels are not open. You can request specific information about available documents by email."}},{"id":"license-contact","type":"text","props":{"title":"info@forrelief.org","body":"Our only official email for all enquiries is info@forrelief.org. Please state the topic in the subject, such as a complaint, privacy or a partnership. We reply to messages sent to info@forrelief.org within 24 hours. Reviewing or resolving a request may take longer depending on its nature."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='en' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='license');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"privacy-0","type":"text","props":{"title":"Politique de confidentialité et de protection des données (conforme au RGPD)","body":"For Relief Humanitarian Foundation vous souhaite la bienvenue. Nous nous engageons à protéger votre vie privée et à préserver la confidentialité de vos données personnelles. Cette politique explique comment nous collectons, utilisons, conservons et protégeons vos données lorsque vous utilisez notre site, nos services numériques ou effectuez un don sur notre plateforme."}},{"id":"privacy-1","type":"text","props":{"title":"Données que nous collectons","body":"• Nom complet\n• Adresse électronique\n• Numéro de téléphone\n• Adresse de résidence ou pays\n• Données relatives aux dons et aux transactions financières\n• Informations du compte lors de l’inscription\n• Communications et demandes de renseignements\n• Informations techniques : adresse IP, type de navigateur et cookies"}},{"id":"privacy-2","type":"text","props":{"title":"Utilisation des données","body":"• Traiter les dons et les paiements\n• Créer et gérer les comptes utilisateurs\n• Communiquer avec les donateurs, bénéficiaires et partenaires\n• Envoyer les reçus, rapports et mises à jour\n• Améliorer les services du site et l’expérience utilisateur\n• Respecter les exigences légales et réglementaires\n• Prévenir la fraude et renforcer la sécurité de la plateforme"}},{"id":"privacy-3","type":"text","props":{"title":"Protection des données","body":"Nous appliquons des mesures techniques et administratives avancées, notamment le chiffrement des données en transit et au repos, des serveurs sécurisés, des contrôles d’accès stricts et une surveillance continue de la sécurité. Nous ne vendons, ne louons ni ne commercialisons vos données personnelles."}},{"id":"privacy-4","type":"text","props":{"title":"Vos droits au titre du RGPD","body":"• Accéder à vos données personnelles\n• Rectifier les données inexactes\n• Demander la suppression des données lorsque la loi le permet\n• Limiter le traitement des données\n• Vous opposer à certains types de traitement\n• Retirer votre consentement à tout moment\n• Demander le transfert des données à un autre prestataire\n• Déposer une réclamation auprès de l’autorité de contrôle compétente"}},{"id":"privacy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='privacy');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"terms-0","type":"text","props":{"title":"Cadre juridique","body":"• La plateforme respecte la législation relative à la protection des consommateurs et au commerce électronique\n• Les exigences de lutte contre le blanchiment et le financement du terrorisme\n• La protection des données personnelles selon les normes internationales\n• Les meilleures pratiques de gouvernance des organismes à but non lucratif"}},{"id":"terms-1","type":"text","props":{"title":"Conditions d’utilisation","body":"• Avoir la capacité juridique de conclure des contrats selon les lois de votre pays\n• Fournir des informations véridiques, exactes et à jour\n• Utiliser des moyens de paiement légaux que vous êtes autorisé à utiliser\n• Respecter toutes les lois et réglementations applicables"}},{"id":"terms-2","type":"text","props":{"title":"Dons","body":"• Les dons sont volontaires et les fonds doivent avoir une origine licite\n• L’organisme peut réaffecter les dons à un projet similaire si le projet choisi est entièrement financé\n• Un don ne constitue ni un achat ni un investissement garantissant des résultats précis"}},{"id":"terms-3","type":"text","props":{"title":"Engagements de l’organisme","body":"• Gérer les dons avec responsabilité et intégrité\n• Émettre immédiatement des reçus électroniques\n• Publier périodiquement des rapports financiers et d’impact\n• Protéger les données personnelles conformément à la politique de confidentialité\n• Appliquer les normes les plus élevées de transparence, de responsabilité et de gouvernance"}},{"id":"terms-4","type":"text","props":{"title":"Exactitude des informations et usage acceptable","body":"Si vous constatez une erreur ou une information à mettre à jour, envoyez le lien de la page à l’adresse officielle. Les réponses de l’assistant automatisé peuvent être incorrectes et ne constituent pas une confirmation officielle de l’organisme. N’utilisez pas le site pour des abus, une usurpation d’identité ou l’envoi d’informations financières sensibles."}},{"id":"terms-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='terms');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"refund-policy-0","type":"text","props":{"title":"Situation actuelle","body":"Les canaux de dons ne sont pas ouverts. Nous ne présentons donc pas de procédure opérationnelle ni de délai garanti de remboursement de dons en ligne. Les conditions seront précisées avant l''ouverture."}},{"id":"refund-policy-1","type":"text","props":{"title":"Somme envoyée ou demande de paiement reçue","body":"Contactez info@forrelief.org en précisant la date, le destinataire ou le lien et les faits. N''envoyez pas de données de carte ou de codes de vérification. Nous pouvons examiner les informations disponibles, sans garantir la récupération de fonds envoyés à un tiers ni l''authenticité d''une demande avant vérification."}},{"id":"refund-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='refund-policy');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"cookie-policy-0","type":"text","props":{"title":"Comment les utilisons-nous ?","body":"• Faire fonctionner les fonctionnalités essentielles et assurer le bon fonctionnement du site\n• Enregistrer les préférences et réglages pour améliorer la navigation\n• Analyser les performances, le nombre de visites et le comportement des utilisateurs\n• Renforcer la sécurité du site et détecter les activités illégales\n• Améliorer les contenus et services selon les besoins des visiteurs"}},{"id":"cookie-policy-1","type":"text","props":{"title":"Gestion des cookies","body":"Vous pouvez accepter, refuser ou supprimer les cookies à tout moment dans les paramètres de votre navigateur. La désactivation de certains cookies peut affecter le fonctionnement de certaines fonctionnalités du site."}},{"id":"cookie-policy-2","type":"text","props":{"title":"Stockage dans le navigateur","body":"Le site utilise des cookies de session pour la connexion et un stockage local pour certaines préférences, comme le choix des cookies et le panier. Vous pouvez supprimer ces données dans les paramètres du navigateur, ce qui peut vous déconnecter ou effacer vos préférences."}},{"id":"cookie-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='cookie-policy');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"aml-policy-0","type":"text","props":{"title":"Expérience institutionnelle et engagement responsable","body":"Notre organisme est actuellement indépendant et bénéficie d’une longue expérience institutionnelle. Nous préservons la confiance de nos soutiens et partenaires par des procédures adaptées à nos activités et aux exigences légales applicables. Les canaux de dons du site ne sont pas encore ouverts ; les engagements suivants décrivent notre approche des fonds et des partenariats."}},{"id":"aml-policy-1","type":"text","props":{"title":"Nos engagements","body":"• Appliquer des mesures efficaces contre le blanchiment, le financement du terrorisme et la fraude.\n• Protéger les fonds des donateurs et garantir leur utilisation aux fins humanitaires prévues.\n• Vérifier l’identité des partenaires et des parties concernées lorsque cela est nécessaire.\n• Surveiller les transactions financières pour détecter les activités inhabituelles ou suspectes.\n• Coopérer avec les autorités compétentes conformément aux exigences légales."}},{"id":"aml-policy-2","type":"text","props":{"title":"Cadre de référence","body":"• Recommandations du Groupe d’action financière (GAFI/FATF).\n• Exigences de lutte contre le blanchiment et le financement du terrorisme (AML/CFT).\n• Régimes de sanctions internationales lorsqu’ils s’appliquent.\n• Législations nationales pertinentes dans les pays où l’organisme intervient."}},{"id":"aml-policy-3","type":"text","props":{"title":"Responsabilités des utilisateurs","body":"• Les fonds donnés doivent avoir une origine licite.\n• Fournir des informations exactes et complètes.\n• Ne pas utiliser la plateforme à des fins illégales ou frauduleuses.\n• Respecter les lois et règlements applicables dans le pays de résidence."}},{"id":"aml-policy-4","type":"text","props":{"title":"Demande suspecte","body":"Envoyez le lien ou la description d''une demande de transfert reçue au nom de l''organisme à l''adresse officielle. Ne partagez aucun mot de passe ou code de vérification. Un logo ne suffit pas à authentifier une demande."}},{"id":"aml-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='aml-policy');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"complaints-0","type":"text","props":{"title":"Une seule adresse","body":"Les questions, réclamations, demandes de confidentialité, de presse et de partenariat passent par info@forrelief.org. Aucun service ne dispose d''une autre adresse annoncée. Indiquez le sujet de votre demande dans l''objet."}},{"id":"complaints-1","type":"text","props":{"title":"Décrire le problème","body":"Précisez le lien ou la date, les faits et un moyen de réponse. Partagez uniquement les informations nécessaires. Des précisions peuvent être demandées ; nous répondons sous 24 heures en précisant la prochaine étape et si un délai supplémentaire est nécessaire. Pour une question de paiement, rappelez que les dons ne sont pas encore ouverts."}},{"id":"complaints-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='complaints');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"financial-transparency-0","type":"text","props":{"title":"Informations disponibles","body":"Les canaux de dons du site ne sont pas ouverts. Les compteurs, objectifs et images ne constituent pas des états financiers ni une preuve de collecte sur la plateforme."}},{"id":"financial-transparency-1","type":"text","props":{"title":"Rapports","body":"Cette page ne revendique pas d''audit indépendant ou de rapport publié sans fournir le document, sa période et sa source. Contactez-nous au sujet d''un rapport ou projet précis. Aucun pourcentage de frais ou d''affectation n''est affirmé sans justificatif."}},{"id":"financial-transparency-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='financial-transparency');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"how-we-use-donations-0","type":"text","props":{"title":"Avant l''ouverture","body":"Les dons ne sont pas encore acceptés par les canaux du site. Les descriptions de projets exposent des activités ou besoins, sans promettre une répartition fixe de fonds non reçus."}},{"id":"how-we-use-donations-1","type":"text","props":{"title":"Lors du lancement","body":"Les informations publiées préciseront les objectifs des campagnes et les frais, limites et conditions pertinents. Nous ne promettons actuellement ni versement intégral de chaque don aux bénéficiaires ni délai d''exécution sans données documentées."}},{"id":"how-we-use-donations-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='how-we-use-donations');
UPDATE "PageTranslation" SET "description"='Les canaux de dons ne sont pas encore ouverts. Leur ouverture sera annoncée lorsqu’ils seront prêts.',"sections"='[{"id":"license-0","type":"text","props":{"title":"Contenus et marques","body":"Les textes, images et marques peuvent appartenir à l''organisme ou à d''autres titulaires de droits. Envoyez le lien concerné pour une demande de réutilisation ou un problème d''attribution."}},{"id":"license-1","type":"text","props":{"title":"Portée de cette page","body":"Le site, le nom de l''organisme ou un lien vers un registre public ne prouve pas à lui seul une autorisation de collecte, une exonération fiscale ou une certification de sécurité. Les dons ne sont pas ouverts. Les documents disponibles peuvent faire l''objet d''une demande précise par e-mail."}},{"id":"license-contact","type":"text","props":{"title":"info@forrelief.org","body":"Notre seule adresse officielle pour toutes les demandes est info@forrelief.org. Précisez le sujet : réclamation, confidentialité ou partenariat, par exemple. Nous répondons aux messages envoyés à info@forrelief.org sous 24 heures. Le traitement ou la résolution peut demander davantage de temps selon la demande."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='fr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='license');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"privacy-0","type":"text","props":{"title":"Gizlilik ve veri koruma politikası (GDPR ile uyumlu)","body":"For Relief Humanitarian Foundation olarak hoş geldiniz diyoruz. Gizliliğinizi korumayı ve kişisel verilerinizin gizliliğini sağlamayı taahhüt ediyoruz. Bu politika, web sitemizi veya dijital hizmetlerimizi kullandığınızda ya da platformumuz üzerinden bağış yaptığınızda verilerinizi nasıl topladığımızı, kullandığımızı, sakladığımızı ve koruduğumuzu açıklar."}},{"id":"privacy-1","type":"text","props":{"title":"Topladığımız veriler","body":"• Ad ve soyadı\n• E-posta adresi\n• Telefon numarası\n• İkamet adresi veya ülke\n• Bağış ve mali işlem verileri\n• Kayıt sırasında hesap bilgileri\n• İletişim ve bilgi talepleri\n• Teknik bilgiler: IP adresi, tarayıcı türü ve çerezler"}},{"id":"privacy-2","type":"text","props":{"title":"Verileri nasıl kullanıyoruz?","body":"• Bağış ve ödemeleri işlemek\n• Kullanıcı hesaplarını oluşturmak ve yönetmek\n• Bağışçılar, yararlanıcılar ve ortaklarla iletişim kurmak\n• Makbuz, rapor ve güncellemeler göndermek\n• Site hizmetlerini ve kullanıcı deneyimini iyileştirmek\n• Yasal ve düzenleyici gerekliliklere uymak\n• Dolandırıcılığı önlemek ve platform güvenliğini güçlendirmek"}},{"id":"privacy-3","type":"text","props":{"title":"Veri koruma","body":"Aktarım ve depolama sırasında veri şifreleme, güvenli sunucular, sıkı erişim kontrolleri ve sürekli güvenlik izleme dahil olmak üzere gelişmiş teknik ve idari önlemler uyguluyoruz. Kişisel verilerinizi satmıyor, kiralamıyor veya ticaretini yapmıyoruz."}},{"id":"privacy-4","type":"text","props":{"title":"GDPR kapsamındaki haklarınız","body":"• Kişisel verilerinize erişmek\n• Yanlış verileri düzeltmek\n• Yasaların izin verdiği durumlarda verilerin silinmesini istemek\n• Veri işlemeyi kısıtlamak\n• Belirli işleme türlerine itiraz etmek\n• Onayı istediğiniz zaman geri çekmek\n• Verilerin başka bir sağlayıcıya aktarılmasını istemek\n• Yetkili denetim makamına şikâyette bulunmak"}},{"id":"privacy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='privacy');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"terms-0","type":"text","props":{"title":"Yasal çerçeve","body":"• Platform, tüketicinin korunması ve elektronik ticaret mevzuatına uyar\n• Kara para aklama ve terörün finansmanıyla mücadele gereklilikleri\n• Uluslararası standartlara uygun kişisel veri koruması\n• Kâr amacı gütmeyen kuruluşlar için en iyi yönetişim uygulamaları"}},{"id":"terms-1","type":"text","props":{"title":"Kullanım uygunluğu","body":"• Ülkenizin yasalarına göre sözleşme yapma ehliyetine sahip olmalısınız\n• Doğru, eksiksiz ve güncel bilgiler sunmalısınız\n• Kullanmaya yetkili olduğunuz yasal ödeme yöntemlerini kullanmalısınız\n• Geçerli tüm yasa ve düzenlemelere uymalısınız"}},{"id":"terms-2","type":"text","props":{"title":"Bağışlar","body":"• Bağışlar özgür iradeyle yapılır ve fonların kaynağı yasal olmalıdır\n• Seçilen projenin finansmanı tamamlanırsa kuruluş bağışları benzer bir projeye yönlendirebilir\n• Bağış, belirli sonuçları garanti eden bir satın alma veya yatırım değildir"}},{"id":"terms-3","type":"text","props":{"title":"Kuruluşun taahhütleri","body":"• Bağışları sorumluluk ve dürüstlükle yönetmek\n• Anında elektronik makbuz düzenlemek\n• Düzenli mali raporlar ve etki raporları yayımlamak\n• Kişisel verileri gizlilik politikasına uygun olarak korumak\n• En yüksek şeffaflık, hesap verebilirlik ve yönetişim standartlarını uygulamak"}},{"id":"terms-4","type":"text","props":{"title":"Bilgilerin doğruluğu ve kabul edilebilir kullanım","body":"Bir hata veya güncellenmesi gereken bilgi fark ederseniz sayfa bağlantısını resmî e-posta adresine gönderin. Otomatik asistanın yanıtları hatalı olabilir ve kuruluşun resmî teyidi sayılmaz. Siteyi kötüye kullanım, kimliğe bürünme veya hassas mali bilgi göndermek için kullanmayın."}},{"id":"terms-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='terms');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"refund-policy-0","type":"text","props":{"title":"Mevcut iade durumu","body":"Bağış kanalları açılmadığından çevrimiçi bağışlar için şu anda işleyen bir iade süreci veya garantili süre sunmuyoruz. Ödeme ve iade koşulları açılıştan önce açıklanacaktır."}},{"id":"refund-policy-1","type":"text","props":{"title":"Para gönderdiyseniz veya ödeme talebi aldıysanız","body":"Tarihi, alıcıyı veya bağlantıyı ve kısa açıklamayı info@forrelief.org adresine gönderin. Kart bilgisi veya doğrulama kodu göndermeyin. Mevcut bilgiler incelenebilir; üçüncü tarafa gönderilen paranın geri alınması veya talebin kuruluşa ait olduğu inceleme öncesinde garanti edilemez."}},{"id":"refund-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='refund-policy');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"cookie-policy-0","type":"text","props":{"title":"Nasıl kullanıyoruz?","body":"• Sitenin temel işlevlerini çalıştırmak ve düzgün çalışmasını sağlamak\n• Gezinme deneyimini iyileştirmek için kullanıcı tercihlerini ve ayarlarını kaydetmek\n• Site performansını, ziyaret sayılarını ve kullanıcı davranışlarını analiz etmek\n• Site güvenliğini güçlendirmek ve yasa dışı faaliyetleri tespit etmek\n• İçerik ve hizmetleri ziyaretçilerin ihtiyaçlarına göre iyileştirmek"}},{"id":"cookie-policy-1","type":"text","props":{"title":"Çerez yönetimi","body":"Tarayıcı ayarlarınızdan çerezleri istediğiniz zaman kabul edebilir, reddedebilir veya silebilirsiniz. Bazı çerezleri devre dışı bırakmak, sitenin bazı işlevlerinin çalışmasını etkileyebilir."}},{"id":"cookie-policy-2","type":"text","props":{"title":"Tarayıcıda depolama","body":"Site, giriş için oturum çerezleri; çerez seçimi ve site sepeti gibi bazı tercihler için yerel depolama kullanır. Bu verileri tarayıcı ayarlarından silebilirsiniz; bu işlem oturumunuzu kapatabilir veya tercihlerinizi kaldırabilir."}},{"id":"cookie-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='cookie-policy');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"aml-policy-0","type":"text","props":{"title":"Kurumsal deneyim ve sorumlu yaklaşım","body":"Kuruluşumuz şu anda bağımsızdır ve uzun yıllara dayanan kurumsal deneyimden yararlanır. Destekçilerimizin ve ortaklarımızın güvenini, faaliyetlerimize ve geçerli yasal gerekliliklere uygun süreçlerle korumayı taahhüt ediyoruz. Sitenin bağış kanalları henüz açık değildir; aşağıdaki taahhütler fonlara ve ortaklıklara kurumsal yaklaşımımızı açıklar."}},{"id":"aml-policy-1","type":"text","props":{"title":"Taahhütlerimiz","body":"• Kara para aklama, terörün finansmanı ve dolandırıcılığa karşı etkili önlemler uygulamak.\n• Bağışçı fonlarını korumak ve belirlenen insani amaçlarla kullanılmasını sağlamak.\n• Gerektiğinde ortakların ve işlem yapılan tarafların kimliklerini doğrulamak.\n• Olağandışı veya şüpheli faaliyetleri tespit etmek için mali işlemleri izlemek.\n• Yasal gereklilikler doğrultusunda yetkili düzenleyici ve denetleyici makamlarla iş birliği yapmak."}},{"id":"aml-policy-2","type":"text","props":{"title":"Referans çerçevesi","body":"• Mali Eylem Görev Gücü (FATF) tavsiyeleri.\n• Kara para aklama ve terörün finansmanıyla mücadele (AML/CFT) gereklilikleri.\n• Uygulanabildiği durumlarda uluslararası yaptırım rejimleri.\n• Kuruluşun faaliyet gösterdiği ülkelerdeki ilgili ulusal mevzuat."}},{"id":"aml-policy-3","type":"text","props":{"title":"Kullanıcı sorumlulukları","body":"• Bağışta kullanılan fonların kaynağı yasal olmalıdır.\n• Doğru ve eksiksiz bilgi sunulmalıdır.\n• Platform yasa dışı veya hileli faaliyetler için kullanılmamalıdır.\n• İkamet edilen ülkede geçerli yasa ve düzenlemelere uyulmalıdır."}},{"id":"aml-policy-4","type":"text","props":{"title":"Şüpheli talep bildirimi","body":"Kuruluş adına gelen transfer talebinin bağlantısını veya açıklamasını resmî adrese gönderin. Parola ve doğrulama kodlarını paylaşmayın. Logo bulunması tek başına talebin gerçek olduğunu göstermez."}},{"id":"aml-policy-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='aml-policy');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"complaints-0","type":"text","props":{"title":"Tüm talepler için tek adres","body":"Sorular, şikâyetler, gizlilik, basın ve ortaklık talepleri info@forrelief.org adresinden alınır. Ayrı bölüm adresleri ilan etmiyoruz. Yönlendirme için konu satırında talebinizi belirtin."}},{"id":"complaints-1","type":"text","props":{"title":"Sorunun iletilmesi","body":"Sayfa bağlantısını veya olay tarihini, açıklamayı ve uygun iletişim yöntemini ekleyin. Yalnızca gerekli bilgileri paylaşın. Ek açıklama istenebilir; 24 saat içinde yanıt vererek sonraki adımı ve ek süre gerekip gerekmediğini açıklıyoruz. Ödemeyle ilgili sorularda bağış kanallarının henüz açılmadığını dikkate alın."}},{"id":"complaints-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='complaints');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"financial-transparency-0","type":"text","props":{"title":"Mevcut bilgiler","body":"Sitenin bağış kanalları açılmadı. Sayaçlar, kampanya hedefleri ve görseller mali tablo veya platform üzerinden para toplandığının kanıtı değildir."}},{"id":"financial-transparency-1","type":"text","props":{"title":"Raporlar","body":"Belge, dönem ve kaynak sunulmadıkça bu sayfa bağımsız mali denetim veya yayımlanmış rapor iddiasında bulunmaz. Belirli bir rapor veya proje için e-postayla bilgi isteyin. Destekleyici kayıt olmadan gider veya tahsis yüzdesi açıklamıyoruz."}},{"id":"financial-transparency-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='financial-transparency');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"how-we-use-donations-0","type":"text","props":{"title":"Kanallar açılmadan önce","body":"Site kanallarından henüz bağış kabul edilmiyor. Proje açıklamaları faaliyet veya ihtiyacı anlatır; henüz alınmamış bağışların sabit oranlarda dağıtılacağı vaadi değildir."}},{"id":"how-we-use-donations-1","type":"text","props":{"title":"Açılışta paylaşılacak bilgiler","body":"Kanallar açıldığında kampanya amacı ve ilgili maliyet, kısıtlama ve koşullar açıklanacaktır. Belgelendirilmiş bilgi olmadan her bağışın tamamının yararlanıcılara ulaşacağını veya belirli uygulama tarihlerini vaat etmiyoruz."}},{"id":"how-we-use-donations-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='how-we-use-donations');
UPDATE "PageTranslation" SET "description"='Bağış kanalları henüz açılmadı. Bağış kabulüne hazır olduğumuzda duyuru yapacağız.',"sections"='[{"id":"license-0","type":"text","props":{"title":"İçerikler ve markalar","body":"Metin, görsel ve markalar kuruluşa veya başka hak sahiplerine ait olabilir. Yeniden kullanım ya da atıf sorunu için ilgili bağlantıyı resmî adrese gönderin."}},{"id":"license-1","type":"text","props":{"title":"Bu sayfanın sınırları","body":"Site, kuruluş adı veya resmî sicil bağlantısı tek başına bağış toplama izni, vergi muafiyeti veya güvenlik sertifikası kanıtı değildir. Bağış kanalları açılmadı. Mevcut belgeler hakkında belirli bilgileri e-postayla isteyebilirsiniz."}},{"id":"license-contact","type":"text","props":{"title":"info@forrelief.org","body":"Tüm sorular için tek resmî e-posta adresimiz info@forrelief.org. Konu satırında şikâyet, gizlilik veya ortaklık gibi talebinizi belirtin. info@forrelief.org adresine gelen mesajlara 24 saat içinde yanıt veriyoruz. Talebin incelenmesi veya çözülmesi, niteliğine göre daha uzun sürebilir."}}]'::jsonb,"updatedAt"=now() WHERE "locale"='tr' AND "pageId" IN (SELECT "id" FROM "Page" WHERE "slug"='license');
COMMIT;
